class Solution {
    public boolean isNStraightHand(int[] hand,int groupSize){
        if(hand.length%groupSize!=0)return false;
        TreeMap<Integer,Integer> count=new TreeMap<>();
        for(int value:hand)count.merge(value,1,Integer::sum);
        while(!count.isEmpty()){
            int start=count.firstKey();
            for(int value=start;value<start+groupSize;value++){
                Integer frequency=count.get(value);
                if(frequency==null)return false;
                if(frequency==1)count.remove(value);
                else count.put(value,frequency-1);
            }
        }
        return true;
    }
}

code.kotlin:
class Solution {
    fun isNStraightHand(hand:IntArray,groupSize:Int):Boolean{
        if(hand.size%groupSize!=0)return false;
        val count=java.util.TreeMap<Int,Int>();
        for(value in hand)count[value]=(count[value]?:0)+1;
        while(count.isNotEmpty()){
            val start=count.firstKey();
            for(value in start until start+groupSize){
                val frequency=count[value]?:return false;
                if(frequency==1)count.remove(value)else count[value]=frequency-1
            }
        };
        return true
    }
}

